    enonce: "أوجد العدد الحقيقي x حيث:<br><span dir=\"ltr\" class=\"expr\">E = 7 - 4<span class=\"rad\"><span class=\"rcd\">3</span></span></span>",
    correction: [{"quoi":"ننطلق من الشكل المفكّك","math":"<span dir=\"ltr\" class=\"expr\">E = (7 - 4<span class=\"rad\"><span class=\"rcd\">3</span></span>)(x - 7)</span>"},{"quoi":"نقسم على <span dir=\"ltr\" class=\"expr\">7 - 4<span class=\"rad\"><span class=\"rcd\">3</span></span></span> غير المعدوم","math":"<span dir=\"ltr\" class=\"expr\">x - 7 = 1</span>"},{"quoi":"نحلّ","math":"<span dir=\"ltr\" class=\"expr\">x = 8</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">E = 7 - 4<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"}],
